		private void SetupZukan() {
			descriptionPanel.SetBgHead(isShowZenkokuZukan);
			zukanInfoList.Clear();

			int getCount = 0;
			int foundCount = 0;

			if (isShowZenkokuZukan)
			{
				getCount = ZukanWork.GetCount(false);
				foundCount = ZukanWork.SeeCount(false);

				bool isExistManafi = false;
				int lastMonsNo = 1;
				for (int monsNo = 1; monsNo <= (int)MonsNo.END; monsNo++)
				{
					if (ZukanWork.GetStatus((uint)monsNo) == GET_STATUS.NONE)
						continue;

					if (monsNo == (int)MonsNo.MANAFI)
					{
						zukanInfoList.Add(new ZukanInfo((MonsNo)monsNo, false));
						isExistManafi = true;
					}
					else
					{
						lastMonsNo = monsNo;
					}
				}

				// The compiled loop skips MANAFI when (isExistManafi || lastMonsNo < MANAFI) (@01a397f4–01a39804); below MANAFI the test never fires.
				bool isSkipManafi = isExistManafi || lastMonsNo < (int)MonsNo.MANAFI;
				for (int monsNo = 1; monsNo <= lastMonsNo; monsNo++)
				{
					if (isSkipManafi && monsNo == (int)MonsNo.MANAFI)
						continue;

					zukanInfoList.Add(new ZukanInfo((MonsNo)monsNo, false));
				}
			}
			else
			{
				getCount = ZukanWork.GetSinouCount(false);
				foundCount = ZukanWork.SeeSinouCount(false);

				bool isExistManafi = false;
				int lastIndex = 0;
				for (int i = 0; i < ZukanWork.ShinouZukanNos.Length; i++)
				{
					if (ZukanWork.GetStatus((uint)ZukanWork.ShinouZukanNos[i]) == GET_STATUS.NONE)
						continue;

					if (ZukanWork.ShinouZukanNos[i] == (int)MonsNo.MANAFI)
					{
						zukanInfoList.Add(new ZukanInfo((MonsNo)ZukanWork.ShinouZukanNos[i], true));
						isExistManafi = true;
					}
					else
					{
						lastIndex = i;
					}
				}

				// Same compiled predicate as the national branch (@01a39a18–01a39a24): the index is compared with MANAFI, the element value is tested.
				bool isSkipManafi = isExistManafi || lastIndex < (int)MonsNo.MANAFI;
				for (int i = 0; i <= lastIndex; i++)
				{
					if (isSkipManafi && ZukanWork.ShinouZukanNos[i] == (int)MonsNo.MANAFI)
						continue;

					zukanInfoList.Add(new ZukanInfo((MonsNo)ZukanWork.ShinouZukanNos[i], true));
				}
			}

			getCountText.SetFormattedText(() => MessageWordSetHelper.SetDigitWord(0, getCount), null, null);
			foundCountText.SetFormattedText(() => MessageWordSetHelper.SetDigitWord(0, foundCount), null, null);
			headerImage.sprite = headerSprites[isShowZenkokuZukan ? 1 : 0];
			titleImage.sprite = UIManager.Instance.GetAtlasSprite(SpriteAtlasID.COMMON_LANG, isShowZenkokuZukan ? "dex_txt_title_01_02" : "dex_txt_title_01_01");
		}
		private void ReloadZukanList(global::Pml.MonsNo selectMonsNo = (global::Pml.MonsNo)(0)) {
			int order;

			viewZukanInfoList.Clear();
			getZukanInfoList.Clear();

			ZUKAN_SORT_TYPE sortType = ZukanWork.GetSortType();
			switch (sortType)
			{
				case ZUKAN_SORT_TYPE.NUMBER:
					buttonViewType = ZukanPokemonInfoButton.ViewType.No;
					viewZukanInfoList.AddRange(zukanInfoList.ToArray());
					viewZukanInfoList.Sort((x, y) => x.ZukanNo.CompareTo(y.ZukanNo));
					break;

				case ZUKAN_SORT_TYPE.INITIAL:
					buttonViewType = ZukanPokemonInfoButton.ViewType.No;
					for (int i = 0; i < zukanInfoList.Count; i++)
					{
						if (zukanInfoList[i].GetStatus != GET_STATUS.NONE)
							viewZukanInfoList.Add(zukanInfoList[i]);
					}
					if (nameSortOrderDic == null)
						CreateNameSortOrderData();

					int orderX, orderY;
					viewZukanInfoList.Sort((x, y) =>
					{
						if (nameSortOrderDic.TryGetValue((int)x.MonsNo, out orderX) && nameSortOrderDic.TryGetValue((int)y.MonsNo, out orderY))
							return orderX.CompareTo(orderY);

						return x.Name.CompareTo(y.Name);
					});
					break;

				case ZUKAN_SORT_TYPE.HEAVIER:
				case ZUKAN_SORT_TYPE.LIGHTER:
					buttonViewType = ZukanPokemonInfoButton.ViewType.Weight;
					for (int i = 0; i < zukanInfoList.Count; i++)
					{
						if (zukanInfoList[i].Weight != 0)
							viewZukanInfoList.Add(zukanInfoList[i]);
					}
					order = sortType == ZUKAN_SORT_TYPE.LIGHTER ? 1 : -1;
					viewZukanInfoList.Sort((x, y) =>
					{
						int result = order * x.Weight.CompareTo(y.Weight);
						if (result != 0)
							return result;

						return x.ZukanNo.CompareTo(y.ZukanNo);
					});
					break;

				case ZUKAN_SORT_TYPE.HIGHER:
				case ZUKAN_SORT_TYPE.LOWER:
					buttonViewType = ZukanPokemonInfoButton.ViewType.Height;
					for (int i = 0; i < zukanInfoList.Count; i++)
					{
						if (zukanInfoList[i].Height != 0)
							viewZukanInfoList.Add(zukanInfoList[i]);
					}
					order = sortType == ZUKAN_SORT_TYPE.LOWER ? 1 : -1;
					viewZukanInfoList.Sort((x, y) =>
					{
						int result = order * x.Height.CompareTo(y.Height);
						if (result != 0)
							return result;

						return x.ZukanNo.CompareTo(y.ZukanNo);
					});
					break;
			}

			List<ZukanInfo> descriptionInfos = new List<ZukanInfo>();
			for (int i = 0; i < viewZukanInfoList.Count; i++)
			{
				switch (viewZukanInfoList[i].GetStatus)
				{
					case GET_STATUS.SEE:
						descriptionInfos.Add(viewZukanInfoList[i]);
						break;

					case GET_STATUS.GET:
						getZukanInfoList.Add(viewZukanInfoList[i]);
						descriptionInfos.Add(viewZukanInfoList[i]);
						break;
				}
			}
			descriptionPanel.SetZukanInfos(descriptionInfos.ToArray());

			if (selectedZukanPokemonInfoButton != null)
			{
				int index = viewZukanInfoList.FindIndex(x => x.ZukanNo.Equals(selectedZukanPokemonInfoButton.Info.ZukanNo));
				ZukanWork.ListIndex = index == -1 ? 0 : index;
				ZukanWork.ListScrollPosition = 0.0f;
			}

			SetSortNameText(sortType);

			if (ZukanWork.ListIndex >= viewZukanInfoList.Count)
			{
				ZukanWork.ListIndex = 0;
				ZukanWork.ListScrollPosition = 0.0f;
			}

			if (selectMonsNo != MonsNo.NULL)
			{
				ZukanWork.ListIndex = viewZukanInfoList.FindIndex(x => x.MonsNo == selectMonsNo);
				ZukanWork.ListScrollPosition = 0.0f;
			}

			listScrolView.Setup(viewZukanInfoList.Count, ZukanWork.ListIndex, ZukanWork.ListScrollPosition, true);
			listScrolView.ResumeMoveSelect();
		}
		private void UpdateKeyGuide() {
			Keyguide.Param param = new Keyguide.Param();

