					param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_LIST_DISTRIBUTION });
				}
				param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_LIST_SORT });
				param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_LIST_RATING });
				if (canSwitchZukan)
					param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_LIST_SWITCH });
				param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_LIST_BACK });
			}
			else
			{
				if (descriptionPanel.CanShowMoving)
					param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_DESCRIPTION_CRY });
				param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_DESCRIPTION_DISTRIBUTION });
				if (descriptionPanel.CanShowCompare)
					param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_DESCRIPTION_SIZE });
				if (descriptionPanel.CanSwitchLanguage)
					param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_DESCRIPTION_SWITCH });
				param.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.POKEDEX_DESCRIPTION_BACK });
			}

			Keyguide keyguide = UIManager.Instance.GetKeyguide(null, true);
			Transform keyguideTransform = keyguide.transform;
			keyguideTransform.SetParent(transform, false);
			keyguideTransform.SetAsLastSibling();
			keyguide.Open(param);
		}
		private void HideKeyGuide() {
			UIManager.Instance.GetKeyguide(null, true).transform.SetAsFirstSibling();
		}
		private void RotateSliderIcon(bool isNegative) {
			sliderIconRectTransform.DOComplete(false);
			float z = isNegative ? -SliderIconRotateValue : SliderIconRotateValue;
			sliderIconRectTransform.DOLocalRotate(new Vector3(0.0f, 0.0f, z), SliderIconRotateDuration, RotateMode.FastBeyond360).SetRelative(true);
		}
		private void RequestLoadModel() {
			ZukanInfo info = selectedZukanPokemonInfoButton.Info;
			if (info.CanShowDescription)
			{
				canShowDescription = true;
				descriptionPanel.SetModelView(info.GetCurrentPokemonParam(), false);
			}
			else
			{
				canShowDescription = false;
				descriptionPanel.SetUnknownModelView();
			}
		}
		private void SwitchZukan() {
			isWaitUpdate = true;
			int siblingIndex = header.GetSiblingIndex();
			float headerHeight = header.rect.height;
			Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SLIDE, null);
			header.SetAsLastSibling();
			fadeImage.DOFade(1.0f, 0.1f).OnComplete(() =>
			{
				header.DOLocalMoveY(headerHeight, 0.5f, false).SetRelative(true).OnComplete(() =>
				{
					isShowZenkokuZukan = !isShowZenkokuZukan;
					showZukanType = isShowZenkokuZukan ? ShowZukanType.Zenkoku : ShowZukanType.Shinou;
					SetupZukan();
					ReloadZukanList(MonsNo.NULL);
					header.DOLocalMoveY(-headerHeight, 0.5f, false).SetRelative(true).OnComplete(() =>
					{
						fadeImage.DOFade(0.0f, 0.1f).OnComplete(() =>
						{
							Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_ZUKAN_SELECT1, null);
							header.SetSiblingIndex(siblingIndex);
							isWaitUpdate = false;
						});
					});
				});
			});
		}
		private void ShowHabitatWindow(global::Pml.PokePara.PokemonParam pokemonParam) {
			_input.inputEnabled = false;
			SaveWorkCurrent();
			UnityAction<UIWindow> saveOnPreClose = onPreClose;
			onPreClose = null;
			Close(_ =>
			{
				ZukanHabitatWindow habitat = UIManager.Instance.CreateUIWindow<ZukanHabitatWindow>(UIWindowID.ZUKAN_HABITAT);
				habitat.onClosed = __ =>
				{
					UIZukan zukan = UIManager.Instance.CreateUIWindow<UIZukan>(UIWindowID.ZUKAN);
					zukan.onPreClose = saveOnPreClose;
					zukan.onClosed = onClosed;
					zukan.Open(habitat.instance.windowId, MonsNo.NULL, showZukanType);
					zukan._prevWindowId = _prevWindowId;
				};
				habitat.Open(new ZukanHabitatWindow.Param { pokemonParam = pokemonParam }, instance.windowId);
			}, UIWindowID.ZUKAN_HABITAT);
		}
		private void ShowMovingWindow(global::Pml.PokePara.PokemonParam pokemonParam) {
			_input.inputEnabled = false;
			SaveWorkCurrent();
			Sequencer.Start(FadeTransition<ZukanMovingWindow>(TransitionFadeFillColor, TransitionFadeDuration, () =>
			{
				Close(_ =>
				{
					ZukanMovingWindow window = UIManager.Instance.CreateUIWindow<ZukanMovingWindow>(UIWindowID.ZUKAN_MOVING);
					window.RegisterCloseOnOpenWindow<UIZukan>(TransitionFadeFillColor, TransitionFadeDuration, __ =>
					{
						UIZukan zukan = UIManager.Instance.CreateUIWindow<UIZukan>(UIWindowID.ZUKAN);
						zukan.onPreClose = onPreClose;
						zukan.onClosed = onClosed;
						zukan.Open(window.instance.windowId, MonsNo.NULL, ShowZukanType.None);
						zukan._prevWindowId = _prevWindowId;
						Audio.AudioManager.Instance.PostEvent(AK.EVENTS.RESUME_EV, 0x100009, false);
						Audio.AudioManager.Instance.PostEvent(AK.EVENTS.RESUME_FIELD, 0x100009, false);
						Audio.AudioManager.Instance.PostEvent(AK.EVENTS.RESUME_ENV, 0x100009, false);
						Audio.AudioManager.Instance.PostEvent(AK.EVENTS.RESUME_WEATHER, 0x100009, false);
					});
					window.Open(new ZukanMovingWindow.Param { pokemonParam = pokemonParam }, instance.windowId);
					Audio.AudioManager.Instance.PostEvent(AK.EVENTS.PAUSE_EV, 0x100009, false);
					Audio.AudioManager.Instance.PostEvent(AK.EVENTS.PAUSE_FIELD, 0x100009, false);
					Audio.AudioManager.Instance.PostEvent(AK.EVENTS.PAUSE_ENV, 0x100009, false);
					Audio.AudioManager.Instance.PostEvent(AK.EVENTS.PAUSE_WEATHER, 0x100009, false);
				}, UIWindowID.ZUKAN_MOVING);
			}));
		}
		private void ShowCompareWindow() {
			_input.inputEnabled = false;
			SaveWorkCurrent();
			Sequencer.Start(FadeTransition<ZukanCompareWindow>(TransitionFadeFillColor, TransitionFadeDuration, () =>
			{
				UnityAction<UIWindow> saveOnPreClose = onPreClose;
				onPreClose = null;
				Close(_ =>
				{
					ZukanCompareWindow window = UIManager.Instance.CreateUIWindow<ZukanCompareWindow>(UIWindowID.ZUKAN_COMPARE);
					window.RegisterCloseOnOpenWindow<UIZukan>(TransitionFadeFillColor, TransitionFadeDuration, __ =>
					{
						UIManager.Instance.modelView.ResetCaches(0, true);
						UIZukan zukan = UIManager.Instance.CreateUIWindow<UIZukan>(UIWindowID.ZUKAN);
						zukan.onPreClose = saveOnPreClose;
						zukan.onClosed = onClosed;
						zukan.Open(window.instance.windowId, window.CurrentZukanInfo.MonsNo, ShowZukanType.None);
						zukan._prevWindowId = _prevWindowId;
					});
					window.Open(new ZukanCompareWindow.Param
					{
						CurrentZukanInfo = descriptionPanel.CurrentZukanInfo,
						SelectableZukanInfoList = getZukanInfoList,
					}, instance.windowId);
				}, UIWindowID.ZUKAN_COMPARE);
			}));
		}
		private void Rating() {
			XLSXContent.UIDatabase.SheetZukanRating ratingData = UIManager.Instance.GetZukanRatingData(isShowZenkokuZukan);
			if (ratingData == null)
				return;

			string[] labelNames = new string[]
			{
				isShowZenkokuZukan ? "92-msg_hyouka_ookido_05" : "92-msg_hyouka_doctor_02",
				ratingData.MessageLabel1,
				ratingData.MessageLabel2,
				ratingData.MessageLabel3,
			};
			Action[] onSets = new Action[]
			{
				() => MessageWordSetHelper.SetDigitWord(0, isShowZenkokuZukan ? ZukanWork.GetCount(false) : ZukanWork.SeeSinouCount(false)),
				() => MessageWordSetHelper.SetPlayerNickNameWord(0),
				() => MessageWordSetHelper.SetPlayerNickNameWord(0),
				() => MessageWordSetHelper.SetPlayerNickNameWord(0),
			};
			msgWindowController.OpenMsgWindow(ratingData.MessageFile, labelNames, onSets, true, false, null, null);
		}
		private void ShowSortListContextMenu() {
			List<string> labelNames = new List<string>();
			List<Action> onSelectActionList = new List<Action>();

			labelNames.Add(NumberSortMessageLabel);
			onSelectActionList.Add(() => SortList(ZUKAN_SORT_TYPE.NUMBER));
			labelNames.Add(NameSortMessageLabel);
			onSelectActionList.Add(() => SortList(ZUKAN_SORT_TYPE.INITIAL));
			labelNames.Add(HeavierSortMessageLabel);
			onSelectActionList.Add(() => SortList(ZUKAN_SORT_TYPE.HEAVIER));
			labelNames.Add(LighterSortMessageLabel);
			onSelectActionList.Add(() => SortList(ZUKAN_SORT_TYPE.LIGHTER));
			labelNames.Add(HigherSortMessageLabel);
			onSelectActionList.Add(() => SortList(ZUKAN_SORT_TYPE.HIGHER));
			labelNames.Add(LowerSortMessageLabel);
			onSelectActionList.Add(() => SortList(ZUKAN_SORT_TYPE.LOWER));
			labelNames.Add(CancelSortMessageLabel);
			onSelectActionList.Add(() => { });

			ContextMenuWindow.Param param = msgWindowController.CreateContextMenuParam(ZukanMessageFileName, labelNames.ToArray());
			param.cancelIndex = labelNames.Count - 1;
			param.useCancel = true;
			param.useLoopAndRepeat = true;
			param.position = contextMenuPosition.position;
			param.pivot = contextMenuPosition.pivot;
			param.seDecide = 0;
			param.seCancel = 0;

			msgWindowController.OpenContextMenu(param, index =>
			{
				Audio.AudioManager.Instance.PlaySe(onSelectActionList.Count - 1 == index ? AK.EVENTS.UI_COMMON_MENU_CLOSE : AK.EVENTS.UI_COMMON_DECIDE, null);
				onSelectActionList[index].Invoke();
			}, null);
		}
		private void SortList(global::DPData.ZUKAN_SORT_TYPE sortType) {
			ZukanWork.SetSortType(sortType);
			ReloadZukanList(MonsNo.NULL);
			Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_SORT_DONE, null);
		}
		private void SetSortNameText(global::DPData.ZUKAN_SORT_TYPE sortType) {
			switch (sortType)
			{
				case ZUKAN_SORT_TYPE.NUMBER:
					sortNameText.text = MessageManager.Instance.GetSimpleMessage(ZukanMessageFileName, NumberSortNameMessageLabel);
					break;
				case ZUKAN_SORT_TYPE.INITIAL:
					sortNameText.text = MessageManager.Instance.GetSimpleMessage(ZukanMessageFileName, NameSortNameMessageLabel);
					break;
				case ZUKAN_SORT_TYPE.HEAVIER:
					sortNameText.text = MessageManager.Instance.GetSimpleMessage(ZukanMessageFileName, HeavierSortNameMessageLabel);
					break;
				case ZUKAN_SORT_TYPE.LIGHTER:
					sortNameText.text = MessageManager.Instance.GetSimpleMessage(ZukanMessageFileName, LighterSortNameMessageLabel);
					break;
				case ZUKAN_SORT_TYPE.HIGHER:
					sortNameText.text = MessageManager.Instance.GetSimpleMessage(ZukanMessageFileName, HigherSortNameMessageLabel);
					break;
				case ZUKAN_SORT_TYPE.LOWER:
					sortNameText.text = MessageManager.Instance.GetSimpleMessage(ZukanMessageFileName, LowerSortNameMessageLabel);
					break;
			}
		}
		private void CreateNameSortOrderData() {
			nameSortOrderDic = new Dictionary<int, int>();
			XLSXContent.SearchIndexData.SheetMonsterName[] monsterNames = UIManager.Instance.searchIndexData.MonsterName;
			int monsNo = 0;
			for (int i = 0; i < monsterNames.Length; i++)
			{
				string[] splits = monsterNames[i].MessageID.Split('_');
				if (int.TryParse(splits[1], out monsNo))
					nameSortOrderDic.Add(monsNo, i);
			}
		}
		private void SaveWorkCurrent() {
			if (descriptionPanel.IsShow)
				ZukanWork.ListIndex = viewZukanInfoList.IndexOf(descriptionPanel.CurrentZukanInfo);

			ZukanWork.ListScrollPosition = 0.0f;
		}
		private void ShowDescriptionPanel() {
			HideKeyGuide();
			descriptionPanel.Set(selectedZukanPokemonInfoButton);
			descriptionPanel.ShowDescription(false, true, () => UpdateKeyGuide());
			ZukanWork.IsShowDescription = true;
			ZukanWork.IsShowShinouZukan = !isShowZenkokuZukan;
		}
		private void HideDescriptionPanel() {
			HideKeyGuide();
			int selectIndex = viewZukanInfoList.IndexOf(descriptionPanel.CurrentZukanInfo);
			listScrolView.Setup(viewZukanInfoList.Count, selectIndex, 0.0f, true);
			descriptionPanel.HideDescription(false, true, true, () => UpdateKeyGuide());
			ZukanWork.IsShowDescription = false;
		}
		public UIZukan() { }
		public enum ShowZukanType
		{
			None = 0,
			Shinou = 1,
			Zenkoku = 2,
		}
	}
